/// Returns true iff a and b are anagrams (same multiset of characters).
pub fn is_anagram(a: &str, b: &str) -> bool {
    if a.len() != b.len() {
        return false;
    }
    let ac: Vec<char> = a.chars().collect();
    let bc: Vec<char> = b.chars().collect();
    ac.into_iter().sorted().eq(bc.into_iter().sorted())
}

