        assert_eq!(s.len(), 0);
        assert_eq!(s.is_empty(), true);
    }

    #[test]
    fn test_stack_len_non_empty() {
        let mut s = Stack::new();
        s.push(1);
        assert_eq!(s.len(), 1);
