fn sum_strings(strs: Vec<&str>) -> i32 {
    let mut total = 0;
    for s in strs {
        match s.parse::<i32>() {
            Ok(num) => total += num,
            Err(_) => break, // If any parse fails, break and return 0
        }
    }
    total
}

fn main() {
    let v = vec!["1", "2", "3", "oops", "4"];
    println!("{}", sum_strings(v));
}

